CREATE TABLE public.comments (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, post_id bigint NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, author_id uuid NOT NULL, handle text NOT NULL, body text NOT NULL CHECK (char_length(body) BETWEEN 1 AND 1000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.comments TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.comments TO authenticated; GRANT ALL ON public.comments TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.comments_id_seq TO authenticated, service_role; ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public comments" ON public.comments FOR SELECT TO anon,authenticated USING (true); CREATE POLICY "Own comments insert" ON public.comments FOR INSERT TO authenticated WITH CHECK (author_id=auth.uid()); CREATE POLICY "Own comments update" ON public.comments FOR UPDATE TO authenticated USING (author_id=auth.uid()) WITH CHECK (author_id=auth.uid()); CREATE POLICY "Own comments delete" ON public.comments FOR DELETE TO authenticated USING (author_id=auth.uid()); CREATE TRIGGER comments_updated BEFORE UPDATE ON public.comments FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.room_messages (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, room text NOT NULL, campus text NOT NULL, author_id uuid NOT NULL, body text NOT NULL CHECK (char_length(body) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.room_messages TO anon; GRANT SELECT, INSERT, UPDATE, DELETE ON public.room_messages TO authenticated; GRANT ALL ON public.room_messages TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.room_messages_id_seq TO authenticated,service_role; ALTER TABLE public.room_messages ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public room messages" ON public.room_messages FOR SELECT TO anon,authenticated USING (true); CREATE POLICY "Own room message insert" ON public.room_messages FOR INSERT TO authenticated WITH CHECK (author_id=auth.uid()); CREATE POLICY "Own room message delete" ON public.room_messages FOR DELETE TO authenticated USING (author_id=auth.uid()); CREATE TRIGGER room_messages_updated BEFORE UPDATE ON public.room_messages FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();